# ============================================================
# AEGIS NIDS - Phase 20 Deploy Script (Security + Dashboard + Docs)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 20 - Security + Dashboard + Documentation"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
    $BackupPath = "$FullPath.phase20_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

$B64_1 = ''
Deploy-File -RelativePath "core/bridge_init.zig" -ExpectedLines 571 -Base64Content $B64_1

$B64_2 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2157 -Base64Content $B64_2

$B64_3 = ''
Deploy-File -RelativePath "aegis_dashboard/src/main.rs" -ExpectedLines 340 -Base64Content $B64_3

$B64_4 = ''
Deploy-File -RelativePath "docs/ARCHITECTURE.md" -ExpectedLines 128 -Base64Content $B64_4

$B64_5 = ''
Deploy-File -RelativePath "docs/DEPLOYMENT.md" -ExpectedLines 118 -Base64Content $B64_5

$B64_6 = ''
Deploy-File -RelativePath "docs/ENV_VARS.md" -ExpectedLines 71 -Base64Content $B64_6


Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 20 fixes applied"
} else {
    Write-Host "[BUILD] FAILED"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 20 changes (Security Holes + Dashboard + Ops + Documentation):"
Write-Host "    B-03:  bridge_init.zig: Added RwLock for fn_bridge_push_event (was TOCTOU on shutdown)"
Write-Host "    GAP-4: aegis_dashboard/main.rs: Fixed log path to aegis_core.ndjson + updated AlertEntry struct"
Write-Host "    OPS-5: nids_analyze.zig: HMAC key moved to AEGIS_RULES_HMAC_KEY env var (was hardcoded)"
Write-Host "    DOC-1: docs/ARCHITECTURE.md: 8-component architecture diagram + data flow + port reference"
Write-Host "    DOC-2: docs/DEPLOYMENT.md: Build order + install + verification + rollback + troubleshooting"
Write-Host "    DOC-3: docs/ENV_VARS.md: All environment variables across all components"
Write-Host "    Effect: 3 security/ops fixes + 3 documentation files (317 lines of docs)"

Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: best practices phase 20 - security + dashboard + docs`""
Write-Host "  git push"
